<?php
require_once __DIR__.'/bootstrap.php';require_admin();$pageTitle='Thư viện ảnh';$active='images';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'add';if($action==='delete'){$id=(int)$_POST['id'];$s=$pdo->prepare("SELECT duong_dan FROM hinhanh_sanpham WHERE id=?");$s->execute([$id]);$path=$s->fetchColumn();$pdo->prepare("DELETE FROM hinhanh_sanpham WHERE id=?")->execute([$id]);delete_local_image(is_string($path)?$path:null);flash('success','Đã xóa ảnh.');}elseif($action==='primary'){$id=(int)$_POST['id'];$s=$pdo->prepare("SELECT san_pham_id FROM hinhanh_sanpham WHERE id=?");$s->execute([$id]);$pid=(int)$s->fetchColumn();$pdo->beginTransaction();$pdo->prepare("UPDATE hinhanh_sanpham SET anh_chinh=0 WHERE san_pham_id=?")->execute([$pid]);$pdo->prepare("UPDATE hinhanh_sanpham SET anh_chinh=1 WHERE id=?")->execute([$id]);$pdo->commit();flash('success','Đã đặt ảnh chính trong thư viện.');}else{$pid=(int)($_POST['san_pham_id']??0);$desc=trim((string)($_POST['mo_ta_anh']??''));$order=(int)($_POST['thu_tu']??0);if(!$pid)throw new RuntimeException('Hãy chọn sản phẩm.');$path=upload_product_image($_FILES['anh']??[]);if(!$path)throw new RuntimeException('Hãy chọn ảnh để tải lên.');$primary=(int)($_POST['anh_chinh']??0);if($primary)$pdo->prepare("UPDATE hinhanh_sanpham SET anh_chinh=0 WHERE san_pham_id=?")->execute([$pid]);$pdo->prepare("INSERT INTO hinhanh_sanpham (san_pham_id,duong_dan,mo_ta_anh,thu_tu,anh_chinh) VALUES (?,?,?,?,?)")->execute([$pid,$path,$desc,$order,$primary]);flash('success','Đã tải ảnh vào thư viện.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof PDOException?'Không thể lưu ảnh. Hãy kiểm tra cấu trúc bảng và dữ liệu.':$e->getMessage());}redirect('images.php'.(!empty($_GET['product_id'])?'?product_id='.(int)$_GET['product_id']:''));}
$products=$pdo->query("SELECT id,ma_san_pham,ten_san_pham FROM sanpham ORDER BY ten_san_pham")->fetchAll();$filter=(int)($_GET['product_id']??0);$sql="SELECT i.*,p.ten_san_pham,p.ma_san_pham FROM hinhanh_sanpham i JOIN sanpham p ON p.id=i.san_pham_id";$params=[];if($filter){$sql.=" WHERE i.san_pham_id=?";$params[]=$filter;}$sql.=" ORDER BY i.san_pham_id,i.anh_chinh DESC,i.thu_tu,i.id DESC";$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();require __DIR__.'/admin-header.php';?>
<section class="panel"><div class="panel-head"><div><h2>Tải ảnh sản phẩm</h2><div class="muted">JPG, PNG hoặc WEBP · tối đa 5 MB mỗi ảnh.</div></div></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>SẢN PHẨM *</label><select name="san_pham_id" required><option value="">Chọn sản phẩm</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" <?=$filter===(int)$p['id']?'selected':''?>><?=e($p['ma_san_pham'].' — '.$p['ten_san_pham'])?></option><?php endforeach;?></select></div><div class="field"><label>TỆP ẢNH *</label><input type="file" name="anh" required accept="image/jpeg,image/png,image/webp"></div><div class="field"><label>MÔ TẢ / ALT</label><input name="mo_ta_anh" placeholder="Ví dụ: Váy hoa nhí chụp chính diện"></div><div class="field"><label>THỨ TỰ</label><input type="number" name="thu_tu" value="0"></div><div class="field"><label><input type="checkbox" name="anh_chinh" value="1"> Đặt làm ảnh chính trong thư viện</label></div></div><div class="form-actions"><button class="btn">Tải ảnh lên</button></div></form></section>
<section class="panel"><div class="panel-head"><div><h2>Ảnh đã tải lên</h2><div class="muted"><?=count($rows)?> ảnh</div></div><form class="searchbar" method="get"><select name="product_id"><option value="0">Tất cả sản phẩm</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" <?=$filter===(int)$p['id']?'selected':''?>><?=e($p['ma_san_pham'])?></option><?php endforeach;?></select><button class="btn light">Lọc</button></form></div><div class="table-wrap"><table><thead><tr><th>Ảnh</th><th>Sản phẩm</th><th>Đường dẫn</th><th>Thứ tự</th><th>Ảnh chính</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty">Chưa có ảnh trong thư viện.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><img class="thumb" src="../<?=e($r['duong_dan'])?>" alt="<?=e($r['mo_ta_anh'])?>"></td><td><?=e($r['ma_san_pham'].' — '.$r['ten_san_pham'])?></td><td><?=e($r['duong_dan'])?><br><small class="muted"><?=e($r['mo_ta_anh'])?></small></td><td><?=$r['thu_tu']?></td><td><?=((int)$r['anh_chinh']===1)?'<span class="badge">Ảnh chính</span>':'—'?></td><td><div class="actions"><?php if(!(int)$r['anh_chinh']):?><form class="inline" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="primary"><button class="btn small light">Đặt chính</button></form><?php endif;?><form class="inline" method="post" onsubmit="return confirm('Xóa ảnh này?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="btn small danger">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/admin-footer.php';?>
